def marcar_taxas(apps, schema_editor):
    """ISS e taxa de turismo já lançados (tipo "servico") passam para o tipo próprio,
    para saírem da base da NFS-e também nas contas antigas. Reconhecidos pela
    descrição que `ContaHospedagem.lancar_taxas` sempre escreveu."""
    LancamentoConta = apps.get_model("reservas", "LancamentoConta")
    servico = LancamentoConta.objects.filter(tipo="servico", natureza="servico")
    servico.filter(descricao__startswith="ISS ").update(tipo="taxa")
    servico.filter(descricao__startswith="Taxa de turismo").update(tipo="taxa")


